1	// Successful operations, member order, equality and copying.
2	import { test, describe } from 'node:test';
3	import assert from 'node:assert/strict';
4	import { applyPatch } from '../jsonpatch.mjs';
5	import { assertPatchError, isNegZero } from './helpers.mjs';
6	
7	const J = JSON.parse;
8	const keys = (x) => Object.keys(x);
9	const op = (o, path, extra = {}) => ({ op: o, path, ...extra });
10	const add = (path, value) => op('add', path, { value });
11	const rep = (path, value) => op('replace', path, { value });
12	const tst = (path, value) => op('test', path, { value });
13	const rem = (path) => op('remove', path);
14	const mv = (from, path) => op('move', path, { from });
15	const cp = (from, path) => op('copy', path, { from });
16	
17	function deepFreeze(x) {
18	  const stack = [x];
19	  while (stack.length) {
20	    const v = stack.pop();
21	    if (v !== null && typeof v === 'object' && !Object.isFrozen(v)) {
22	      Object.freeze(v);
23	      stack.push(...Object.values(v));
24	    }
25	  }
26	  return x;
27	}
28	
29	describe('own members only on objects', () => {
30	  const inherited = ['__proto__', 'constructor', 'toString', 'hasOwnProperty', 'valueOf'];
31	  for (const name of inherited) {
32	    for (const mk of [() => tst(`/${name}`, 1), () => rem(`/${name}`), () => rep(`/${name}`, 1)]) {
33	      test(`${mk().op} /${name} on {} is path not found`, () => {
34	        assertPatchError(() => applyPatch({}, [mk()]), 'operation 0: path not found', 0);
35	      });
36	    }
37	  }
38	
39	  test('remove /__proto__ removes the own member', () => {
40	    const r = applyPatch(J('{"__proto__":1,"constructor":2,"toString":3}'), [rem('/__proto__')]);
41	    assert.deepEqual(keys(r), ['constructor', 'toString']);
42	    assert.equal(Object.hasOwn(r, '__proto__'), false);
43	  });
44	
45	  test('replace /__proto__ sets the own member and keeps the prototype', () => {
46	    const r = applyPatch(J('{"__proto__":1,"constructor":2}'), [rep('/__proto__', 9)]);
47	    assert.equal(Object.getOwnPropertyDescriptor(r, '__proto__').value, 9);
48	    assert.equal(Object.getPrototypeOf(r), Object.prototype);
49	    assert.deepEqual(keys(r), ['__proto__', 'constructor']);
50	  });
51	
52	  test('add /__proto__ to {} creates an own member', () => {
53	    const r = applyPatch({}, [add('/__proto__', J('{"x":1}'))]);
54	    assert.equal(Object.hasOwn(r, '__proto__'), true);
55	    assert.deepEqual(keys(r), ['__proto__']);
56	    assert.equal(Object.getPrototypeOf(r), Object.prototype);
57	    assert.equal(r.x, undefined);
58	    assert.deepStrictEqual(Object.getOwnPropertyDescriptor(r, '__proto__').value, J('{"x":1}'));
59	  });
